/* ---------- Motor de idioma compartido ---------- */
window.I18n = (function () {
  const codes = LANGS.map(l => l.code);
  function detect(preferred) {
    const url = new URLSearchParams(location.search).get("lang");
    if (url && codes.includes(url)) return url;
    let saved = null;
    try { saved = localStorage.getItem("lang"); } catch (e) {}
    if (saved && codes.includes(saved)) return saved;
    if (preferred && codes.includes(preferred)) return preferred;
    const nav = (navigator.languages || [navigator.language || ""]).map(x => (x || "").slice(0, 2).toLowerCase());
    for (const n of nav) if (codes.includes(n)) return n;
    return (window.SITE_CONFIG && SITE_CONFIG.defaultLang) || "es";
  }
  let current = "es";
  function t(key, vars) {
    let s = (I18N[current] && I18N[current][key]) || I18N.en[key] || I18N.es[key] || key;
    if (vars) for (const k in vars) s = s.split("{" + k + "}").join(vars[k]);
    return s;
  }
  function set(code, persist) {
    if (!codes.includes(code)) code = "es";
    current = code;
    if (persist) { try { localStorage.setItem("lang", code); } catch (e) {} }
    const meta = LANGS.find(l => l.code === code);
    document.documentElement.lang = code;
    document.documentElement.dir = meta && meta.rtl ? "rtl" : "ltr";
    apply(document);
    document.dispatchEvent(new CustomEvent("langchange", { detail: code }));
  }
  function apply(root) {
    root.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = t(el.dataset.i18n); });
    root.querySelectorAll("[data-i18n-ph]").forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
    root.querySelectorAll("[data-i18n-title]").forEach(el => { el.title = t(el.dataset.i18nTitle); });
  }
  function select(el, onChange) {
    el.innerHTML = LANGS.map(l => `<option value="${l.code}">${l.flag} ${l.name}</option>`).join("");
    el.value = current;
    el.addEventListener("change", () => { set(el.value, true); if (onChange) onChange(el.value); });
    document.addEventListener("langchange", e => { el.value = e.detail; });
  }
  return { detect, t, set, apply, select, get lang() { return current; } };
})();
